// The world `repo bench --remote` meets with every precondition met: bench.yml, a pushed clean HEAD, and gh's runs.
import { REMOTE_GIT, SHA, bench, ok, rawOn, type BenchWorld } from "./bench-world.ts";

export const BENCH_YML: Record<string, string> = {
  ".github/workflows/bench.yml": "# @generated by @workerstack/repo\nname: bench\n",
};
export const MAC = {
  arch: "arm64",
  cores: 3,
  cpu: "Apple M1",
  label: "macos-latest",
  memoryBytes: 7 * 1024 ** 3,
  platform: "darwin",
};
export const WIN = {
  arch: "x64",
  cores: 4,
  cpu: "AMD EPYC 7763",
  label: "windows-latest",
  memoryBytes: 16 * 1024 ** 3,
  platform: "win32",
};

/** `gh run view`'s answer: the run's status and conclusion, and each job as [name, conclusion]. */
export function view(status: string, conclusion: string, jobs: [string, string][] = []) {
  return ok(JSON.stringify({ conclusion, jobs: jobs.map(([name, c]) => ({ conclusion: c, name })), status }));
}
/** One run in `gh run list`'s answer, created at minute `minute` past 10:00. */
export function listed(databaseId: number, headSha: string, [event, minute]: [string, number]) {
  const createdAt = `2026-11-12T10:0${minute}:00Z`;
  return { createdAt, databaseId, event, headSha, url: `https://github.com/o/r/actions/runs/${databaseId}` };
}

/** Decoys around the dispatched run 123: a newer push run at HEAD and a newer dispatch at another commit. */
const RUNS = [
  listed(124, SHA, ["push", 5]),
  listed(125, "f".repeat(40), ["workflow_dispatch", 6]),
  listed(123, SHA, ["workflow_dispatch", 4]),
];
const JOBS: [string, string][] = [
  ["bench (macos-latest)", "success"],
  ["bench (windows-latest)", "success"],
];

/** gh with the run appearing on the second list and completing on the second look. */
export const GH = {
  "run list": [ok("[]"), ok(JSON.stringify(RUNS))],
  "run view 123": [view("in_progress", ""), view("completed", "success", JOBS)],
  "workflow run": ok(),
};

/** `--remote` for startup with every precondition met, and `change` over the world. */
export function remote(change: BenchWorld = {}): ReturnType<typeof bench> {
  const artifacts = { "macos-latest": rawOn(MAC), "windows-latest": rawOn(WIN) };
  return bench(["startup", "--remote"], { artifacts, files: BENCH_YML, gh: GH, git: REMOTE_GIT, ...change });
}
